--
-- Name: apply_merit_progression(); Type: FUNCTION; Schema: avaliacao; Owner: -
--

CREATE FUNCTION avaliacao.apply_merit_progression() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_target_salary numeric(14,2);
  v_level_code text;
  v_level_name text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status OR NEW.status <> 'applied'::hr.progression_status THEN
    RETURN NEW;
  END IF;

  IF NEW.target_salary_range_level_id IS NULL THEN
    RAISE EXCEPTION 'Applied progression % must have target_salary_range_level_id', NEW.id;
  END IF;

  SELECT
    avaliacao.fn_get_vencimento_vigente(NEW.target_salary_range_level_id, NEW.data_efeito),
    level.code,
    level.name
  INTO v_target_salary, v_level_code, v_level_name
  FROM hr.salary_range_level level
  WHERE level.id = NEW.target_salary_range_level_id
    AND level.tenant_id = NEW.tenant_id;

  IF v_target_salary IS NULL THEN
    RAISE EXCEPTION 'Target salary range level % not found for tenant %', NEW.target_salary_range_level_id, NEW.tenant_id;
  END IF;

  INSERT INTO hr.salary_level_history (
    tenant_id,
    employee_id,
    salary_range_level_id,
    salary_reference_id,
    level_code,
    level_description,
    adjustment_amount,
    effective_on,
    vigencia_inicio,
    vigencia_fim,
    vencimento_basico,
    motivo,
    lei_referencia
  )
  VALUES (
    NEW.tenant_id,
    NEW.employee_id,
    NEW.target_salary_range_level_id,
    NEW.target_salary_reference_id,
    v_level_code,
    v_level_name,
    0,
    NEW.data_efeito,
    NEW.data_efeito,
    NULL,
    v_target_salary,
    'reestruturacao',
    COALESCE(NEW.appointment_act, '')
  )
  ON CONFLICT DO NOTHING;

  UPDATE hr.employee
  SET salary_range_level_id = NEW.target_salary_range_level_id,
    salary_reference_id = COALESCE(NEW.target_salary_reference_id, salary_reference_id),
    updated_at = now()
  WHERE id = NEW.employee_id
    AND tenant_id = NEW.tenant_id;

  NEW.applied_at = COALESCE(NEW.applied_at, now());
  RETURN NEW;
END;
$$;


--
-- Name: fn_get_vencimento_vigente(uuid, date); Type: FUNCTION; Schema: avaliacao; Owner: -
--

CREATE FUNCTION avaliacao.fn_get_vencimento_vigente(p_salary_range_level_id uuid, p_competencia date) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (
      SELECT history.vencimento_basico
      FROM hr.salary_level_history history
      WHERE history.salary_range_level_id = p_salary_range_level_id
        AND history.vigencia_inicio <= p_competencia
        AND (history.vigencia_fim IS NULL OR history.vigencia_fim >= p_competencia)
      ORDER BY history.vigencia_inicio DESC
      LIMIT 1
    ),
    (
      SELECT level.base_salary
      FROM hr.salary_range_level level
      WHERE level.id = p_salary_range_level_id
    ),
    0
  )::numeric(14,2);
$$;


--
-- Name: audit_endpoint_circuit_state_mutation(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.audit_endpoint_circuit_state_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row esocial.endpoint_circuit_state;
  v_action text;
BEGIN
  v_row := COALESCE(NEW, OLD);
  v_action := CASE TG_OP
    WHEN 'INSERT' THEN 'CREATE'
    WHEN 'UPDATE' THEN 'UPDATE'
    ELSE 'DELETE'
  END;
  PERFORM public.sgp_append_audit_event(
    v_action,
    'esocial.endpoint_circuit_state',
    v_row.endpoint_url,
    NULL,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'esocial.endpoint_circuit_state',
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object(
      'endpointUrl', v_row.endpoint_url,
      'state', v_row.state::text,
      'failureCount', v_row.failure_count,
      'lastFailureAt', v_row.last_failure_at
    ),
    NULL,
    NULL,
    NULL
  );
  RETURN v_row;
END
$$;


--
-- Name: audit_event_retry_schedule_mutation(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.audit_event_retry_schedule_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  row_value esocial.event_retry_schedule;
  audit_action text;
BEGIN
  row_value := COALESCE(NEW, OLD);
  audit_action := CASE TG_OP
    WHEN 'INSERT' THEN 'CREATE'
    WHEN 'UPDATE' THEN 'UPDATE'
    ELSE 'DELETE'
  END;

  PERFORM set_config('app.current_tenant_id', row_value.tenant_id::text, true);
  PERFORM public.sgp_append_audit_event(
    audit_action,
    'esocial.event_retry_schedule',
    row_value.event_id::text,
    NULL,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'esocial.event_retry_schedule',
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object(
      'attempt', row_value.attempt,
      'nextAt', row_value.next_at,
      'lastError', row_value.last_error
    ),
    NULL,
    NULL,
    NULL
  );
  RETURN row_value;
END
$$;


--
-- Name: audit_s1xxx_dispatch_state_mutation(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.audit_s1xxx_dispatch_state_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  row_after esocial.s1xxx_dispatch_state;
  row_before esocial.s1xxx_dispatch_state;
  audit_action text;
BEGIN
  row_after := NEW;
  row_before := OLD;
  audit_action := CASE TG_OP
    WHEN 'INSERT' THEN 'CREATE'
    WHEN 'UPDATE' THEN 'UPDATE'
    ELSE 'DELETE'
  END;

  PERFORM set_config(
    'app.current_tenant_id',
    COALESCE(row_after.tenant_id, row_before.tenant_id)::text,
    true
  );

  PERFORM public.sgp_append_audit_event(
    audit_action,
    'esocial.s1xxx_dispatch_state',
    COALESCE(row_after.source_entity_id, row_before.source_entity_id),
    NULL::uuid,
    NULL::text,
    NULL::text,
    'esocial.s1xxx_dispatch_state',
    NULL::text,
    jsonb_build_object(
      'eventKind', COALESCE(row_after.event_kind, row_before.event_kind)::text,
      'lastPayloadHash', COALESCE(row_after.last_payload_hash, row_before.last_payload_hash)
    ),
    NULL::text,
