--
-- Name: sgp_s3000_is_periodic(text); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.sgp_s3000_is_periodic(p_event_kind text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_event_kind IN (
    'S-1200',
    'S-1202',
    'S-1207',
    'S-1210',
    'S-1280',
    'S-1300'
  )
$$;


--
-- Name: sgp_s3000_prepare_request(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.sgp_s3000_prepare_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_event public.esocial_event;
  v_block_reason text;
BEGIN
  SELECT * INTO v_event
  FROM public.esocial_event
  WHERE id = NEW.target_event_id
    AND tenant_id = NEW.tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'S-3000 target event not found for tenant' USING ERRCODE = '23503';
  END IF;

  IF v_event.receipt_number IS NULL AND NULLIF(btrim(v_event.reference), '') IS NULL THEN
    RAISE EXCEPTION 'S-3000 target event requires accepted receipt' USING ERRCODE = '23514';
  END IF;

  IF v_event.status <> 'PROCESSADO_COM_SUCESSO'::public."ESocialEventStatus" THEN
    RAISE EXCEPTION 'S-3000 target event must be accepted before exclusion' USING ERRCODE = '23514';
  END IF;

  NEW.target_event_kind := COALESCE(NULLIF(btrim(NEW.target_event_kind), ''), v_event.event_type);
  NEW.target_recibo := COALESCE(NULLIF(btrim(NEW.target_recibo), ''), v_event.receipt_number, v_event.reference);
  NEW.updated_at := now();

  IF esocial.sgp_s3000_is_periodic(NEW.target_event_kind) THEN
    SELECT 'periodic_competence_closed_by_s1299'
    INTO v_block_reason
    FROM esocial.s1299_emission_state state
    WHERE state.tenant_id = NEW.tenant_id
      AND state.competence = to_date(v_event.competence || '-01', 'YYYY-MM-DD')
      AND state.status = 'ACCEPTED'::esocial.s1299_emission_status
    LIMIT 1;

    IF v_block_reason IS NOT NULL THEN
      NEW.status := 'BLOCKED';
      NEW.block_reason := v_block_reason;
    END IF;
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: sgp_s3000_request_audit(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.sgp_s3000_request_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row esocial.s3000_request;
  v_action text;
BEGIN
  v_row := COALESCE(NEW, OLD);
  v_action := CASE TG_OP WHEN 'INSERT' THEN 'CREATE' WHEN 'UPDATE' THEN 'UPDATE' ELSE 'DELETE' END;
  PERFORM set_config('app.current_tenant_id', v_row.tenant_id::text, true);
  PERFORM public.sgp_append_audit_event(
    v_action,
    'esocial.s3000_request',
    v_row.request_id::text,
    v_row.requested_by_user_id,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'esocial.s3000_request',
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object(
      'targetEventId', v_row.target_event_id::text,
      'targetRecibo', v_row.target_recibo,
      'targetEventKind', v_row.target_event_kind,
      'status', v_row.status::text,
      'blockReason', v_row.block_reason,
      'requestedByUserId', v_row.requested_by_user_id,
      'justification', v_row.justification
    ),
    v_row.justification,
    NULL::text,
    NULL::text
  );
  RETURN v_row;
END
$$;


--
-- Name: trg_employee_dependent_s2205_pending(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.trg_employee_dependent_s2205_pending() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  row_after hr.employee_dependent;
  row_before hr.employee_dependent;
BEGIN
  row_after := NEW;
  row_before := OLD;
  PERFORM esocial.enqueue_s2205_pending_alteration(
    COALESCE(row_after.tenant_id, row_before.tenant_id),
    COALESCE(row_after.employee_id, row_before.employee_id),
    'dependent.*',
    'hr.employee_dependent',
    COALESCE(row_after.id, row_before.id),
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(row_before) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(row_after) END
  );
  RETURN COALESCE(NEW, OLD);
END
$$;


--
-- Name: trg_employee_s2205_pending(); Type: FUNCTION; Schema: esocial; Owner: -
--

CREATE FUNCTION esocial.trg_employee_s2205_pending() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  old_zip text;
  new_zip text;
  old_street text;
  new_street text;
BEGIN
  old_zip := COALESCE(OLD.address->>'zip', OLD.address->>'cep');
  new_zip := COALESCE(NEW.address->>'zip', NEW.address->>'cep');
  old_street := COALESCE(OLD.address->>'street', OLD.address->>'dscLograd');
  new_street := COALESCE(NEW.address->>'street', NEW.address->>'dscLograd');

  IF old_zip IS DISTINCT FROM new_zip THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'address.zip', 'hr.employee', NEW.id,
      jsonb_build_object('zip', old_zip),
      jsonb_build_object('zip', new_zip)
    );
  END IF;
  IF old_street IS DISTINCT FROM new_street THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'address.street', 'hr.employee', NEW.id,
      jsonb_build_object('street', old_street),
      jsonb_build_object('street', new_street)
    );
  END IF;
  IF OLD.email IS DISTINCT FROM NEW.email THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'contact.email', 'hr.employee', NEW.id,
      jsonb_build_object('email', OLD.email),
      jsonb_build_object('email', NEW.email)
    );
  END IF;
  IF OLD.phone IS DISTINCT FROM NEW.phone THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'contact.phone', 'hr.employee', NEW.id,
      jsonb_build_object('phone', OLD.phone),
      jsonb_build_object('phone', NEW.phone)
    );
  END IF;
  IF OLD.marital_status IS DISTINCT FROM NEW.marital_status THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'marital_status', 'hr.employee', NEW.id,
      jsonb_build_object('maritalStatus', OLD.marital_status),
      jsonb_build_object('maritalStatus', NEW.marital_status)
    );
  END IF;
  IF OLD.education_level IS DISTINCT FROM NEW.education_level THEN
    PERFORM esocial.enqueue_s2205_pending_alteration(
      NEW.tenant_id, NEW.id, 'education_level', 'hr.employee', NEW.id,
      jsonb_build_object('educationLevel', OLD.education_level),
      jsonb_build_object('educationLevel', NEW.education_level)
    );
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: assert_no_dctfweb_for_competence(uuid, date); Type: FUNCTION; Schema: fiscal; Owner: -
--

CREATE FUNCTION fiscal.assert_no_dctfweb_for_competence(p_tenant_id uuid, p_competence date) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM fiscal.dctfweb_declaration declaration
    WHERE declaration.tenant_id = p_tenant_id
      AND declaration.competence = date_trunc('month', p_competence)::date
      AND declaration.status IN ('TRANSMITTED'::fiscal.dctfweb_declaration_status, 'ACCEPTED'::fiscal.dctfweb_declaration_status)
  ) THEN
    RAISE EXCEPTION 'GPS residual duplicates transmitted or accepted DCTFWeb for competence %', p_competence
      USING ERRCODE = 'P0001', HINT = 'GPSDuplicatesDCTFWebError';
  END IF;
END
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: yearly_income_aggregate; Type: TABLE; Schema: fiscal; Owner: -
--

CREATE TABLE fiscal.yearly_income_aggregate (
    tenant_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    year_base integer NOT NULL,
    taxable_total numeric(14,2) DEFAULT 0 NOT NULL,
    thirteenth_salary numeric(14,2) DEFAULT 0 NOT NULL,
    vacation_total numeric(14,2) DEFAULT 0 NOT NULL,
    severance_total numeric(14,2) DEFAULT 0 NOT NULL,
    exempt_total numeric(14,2) DEFAULT 0 NOT NULL,
    inss_rpps_total numeric(14,2) DEFAULT 0 NOT NULL,
    irrf_total numeric(14,2) DEFAULT 0 NOT NULL,
    dependents_count integer DEFAULT 0 NOT NULL,
    recomputed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT yearly_income_aggregate_money_chk CHECK (((taxable_total >= (0)::numeric) AND (thirteenth_salary >= (0)::numeric) AND (vacation_total >= (0)::numeric) AND (severance_total >= (0)::numeric) AND (exempt_total >= (0)::numeric) AND (inss_rpps_total >= (0)::numeric) AND (irrf_total >= (0)::numeric) AND (dependents_count >= 0))),
    CONSTRAINT yearly_income_aggregate_year_chk CHECK (((year_base >= 2000) AND (year_base <= 2100)))
);

ALTER TABLE ONLY fiscal.yearly_income_aggregate FORCE ROW LEVEL SECURITY;


--
-- Name: recompute_yearly_income(uuid, uuid, integer); Type: FUNCTION; Schema: fiscal; Owner: -
--

CREATE FUNCTION fiscal.recompute_yearly_income(p_tenant_id uuid, p_employee_id uuid, p_year_base integer) RETURNS fiscal.yearly_income_aggregate
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id uuid;
  v_result fiscal.yearly_income_aggregate;
BEGIN
  SELECT employee.tenant_id
  INTO v_tenant_id
  FROM hr.employee employee
  WHERE employee.id = p_employee_id
    AND (p_tenant_id IS NULL OR employee.tenant_id = p_tenant_id);

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Employee % not found for yearly income recompute', p_employee_id;
  END IF;

  IF NOT (
    public.sgp_bypass_rls()
    OR (
      public.sgp_tenant_matches(v_tenant_id)
      AND (
        public.sgp_has_any_permission(ARRAY['fiscal.yearly_income.write', 'fiscal.yearly_income.read', 'report.payslip.read'])
        OR p_employee_id = public.sgp_current_employee_id()
      )
    )
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions for yearly income recompute';
  END IF;

  WITH item_totals AS (
    SELECT
      item.tenant_id,
      item.employee_id,
      item.competence_year AS year_base,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'EARNING'::public."PayrollEntryKind"
          AND earning.taxable = true
      ), 0)::numeric(14,2) AS taxable_total,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'EARNING'::public."PayrollEntryKind"
          AND earning.taxable = true
          AND (
            earning.code ILIKE '%13%'
            OR earning.description ILIKE '%decimo%'
            OR earning.description ILIKE '%décimo%'
          )
      ), 0)::numeric(14,2) AS thirteenth_salary,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'EARNING'::public."PayrollEntryKind"
          AND earning.taxable = true
          AND (
            earning.description ILIKE '%ferias%'
            OR earning.description ILIKE '%férias%'
          )
      ), 0)::numeric(14,2) AS vacation_total,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'EARNING'::public."PayrollEntryKind"
          AND earning.taxable = true
          AND (
            earning.description ILIKE '%rescis%'
            OR item.notes ILIKE '%rescis%'
          )
      ), 0)::numeric(14,2) AS severance_total,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'EARNING'::public."PayrollEntryKind"
          AND earning.taxable = false
      ), 0)::numeric(14,2) AS exempt_total,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'DEDUCTION'::public."PayrollEntryKind"
          AND (
            earning.description ILIKE '%inss%'
            OR earning.description ILIKE '%rpps%'
            OR earning.description ILIKE '%previd%'
          )
      ), 0)::numeric(14,2) AS inss_rpps_total,
      COALESCE(sum(item.amount) FILTER (
        WHERE earning.kind = 'DEDUCTION'::public."PayrollEntryKind"
          AND (
            earning.description ILIKE '%irrf%'
            OR earning.description ILIKE '%imposto de renda%'
          )
      ), 0)::numeric(14,2) AS irrf_total
    FROM payroll.v_payroll_run_line_active item
    JOIN payroll.payroll_earning_deduction earning
      ON earning.id = item.earning_deduction_id
    JOIN payroll.payroll_run run
      ON run.id = item.payroll_run_id
     AND run.tenant_id = item.tenant_id
     AND run.status IN (
       'GENERATED'::public."PayrollRunStatus",
       'APPROVED'::public."PayrollRunStatus",
       'PAID'::public."PayrollRunStatus",
       'CLOSED'::public."PayrollRunStatus"
     )
    WHERE item.tenant_id = v_tenant_id
      AND item.employee_id = p_employee_id
      AND item.competence_year = p_year_base
    GROUP BY item.tenant_id, item.employee_id, item.competence_year
  ),
  dependent_totals AS (
    SELECT
      dependent.tenant_id,
      dependent.employee_id,
      count(*)::integer AS dependents_count
    FROM hr.employee_dependent dependent
    WHERE dependent.tenant_id = v_tenant_id
      AND dependent.employee_id = p_employee_id
      AND dependent.income_tax_dependent = true
    GROUP BY dependent.tenant_id, dependent.employee_id
  ),
  source AS (
    SELECT
      v_tenant_id AS tenant_id,
      p_employee_id AS employee_id,
      p_year_base AS year_base,
      COALESCE(item_totals.taxable_total, 0)::numeric(14,2) AS taxable_total,
      COALESCE(item_totals.thirteenth_salary, 0)::numeric(14,2) AS thirteenth_salary,
      COALESCE(item_totals.vacation_total, 0)::numeric(14,2) AS vacation_total,
      COALESCE(item_totals.severance_total, 0)::numeric(14,2) AS severance_total,
      COALESCE(item_totals.exempt_total, 0)::numeric(14,2) AS exempt_total,
      COALESCE(item_totals.inss_rpps_total, 0)::numeric(14,2) AS inss_rpps_total,
      COALESCE(item_totals.irrf_total, 0)::numeric(14,2) AS irrf_total,
      COALESCE(dependent_totals.dependents_count, 0)::integer AS dependents_count
    FROM (SELECT 1) seed
    LEFT JOIN item_totals
      ON item_totals.tenant_id = v_tenant_id
     AND item_totals.employee_id = p_employee_id
     AND item_totals.year_base = p_year_base
    LEFT JOIN dependent_totals
      ON dependent_totals.tenant_id = v_tenant_id
     AND dependent_totals.employee_id = p_employee_id
  )
  INSERT INTO fiscal.yearly_income_aggregate (
    tenant_id,
    employee_id,
    year_base,
    taxable_total,
    thirteenth_salary,
    vacation_total,
    severance_total,
    exempt_total,
    inss_rpps_total,
    irrf_total,
    dependents_count,
    recomputed_at
  )
  SELECT
    tenant_id,
    employee_id,
    year_base,
    taxable_total,
    thirteenth_salary,
    vacation_total,
    severance_total,
    exempt_total,
    inss_rpps_total,
    irrf_total,
    dependents_count,
    now()
  FROM source
  ON CONFLICT (tenant_id, employee_id, year_base) DO UPDATE
  SET taxable_total = EXCLUDED.taxable_total,
      thirteenth_salary = EXCLUDED.thirteenth_salary,
      vacation_total = EXCLUDED.vacation_total,
      severance_total = EXCLUDED.severance_total,
      exempt_total = EXCLUDED.exempt_total,
      inss_rpps_total = EXCLUDED.inss_rpps_total,
      irrf_total = EXCLUDED.irrf_total,
      dependents_count = EXCLUDED.dependents_count,
      recomputed_at = now()
  RETURNING * INTO v_result;

  PERFORM set_config('app.current_tenant_id', v_result.tenant_id::text, true);
  PERFORM public.sgp_append_audit_event(
    'GENERATE',
    'fiscal.yearly_income_aggregate',
    v_result.employee_id::text || ':' || v_result.year_base::text,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'fiscal.yearly_income_aggregate',
    NULLIF(current_setting('app.request_id', true), ''),
    to_jsonb(v_result),
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN v_result;
END
$$;


--
-- Name: sgp_dctfweb_audit(); Type: FUNCTION; Schema: fiscal; Owner: -
--

CREATE FUNCTION fiscal.sgp_dctfweb_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  row_after record;
  row_before record;
  after_json jsonb;
  before_json jsonb;
  audit_action text;
  resource_id text;
  tenant_value uuid;
BEGIN
  row_after := NEW;
  row_before := OLD;
  after_json := to_jsonb(row_after);
  before_json := to_jsonb(row_before);
  audit_action := CASE TG_OP WHEN 'INSERT' THEN 'CREATE' WHEN 'UPDATE' THEN 'UPDATE' ELSE 'DELETE' END;
  resource_id := COALESCE(
    after_json ->> 'id',
    before_json ->> 'id',
    after_json ->> 'declaracao_id',
    before_json ->> 'declaracao_id'
  );
  tenant_value := COALESCE(row_after.tenant_id, row_before.tenant_id);

  PERFORM set_config('app.current_tenant_id', tenant_value::text, true);
  PERFORM public.sgp_append_audit_event(
    audit_action,
    TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
    resource_id,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object('operation', TG_OP, 'before', before_json, 'after', after_json),
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN COALESCE(NEW, OLD);
END
$$;


