--
-- Name: sgp_hr02_employment_link_timeline(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr02_employment_link_timeline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
    AND NEW.contract_type IS NOT DISTINCT FROM OLD.contract_type
    AND NEW.functional_status_id IS NOT DISTINCT FROM OLD.functional_status_id
  THEN
    RETURN NEW;
  END IF;

  INSERT INTO hr.employee_status_history (
    tenant_id,
    employee_id,
    functional_status_id,
    starts_on,
    ends_on,
    notes
  )
  SELECT
    e.tenant_id,
    e.id,
    COALESCE(NEW.functional_status_id, e.functional_status_id),
    CURRENT_DATE,
    NEW.end_date,
    concat('Alteracao de regime juridico: ', NEW.contract_type)
  FROM hr.employee e
  WHERE e.tenant_id = NEW.tenant_id
    AND e.employment_link_id = NEW.id
    AND COALESCE(NEW.functional_status_id, e.functional_status_id) IS NOT NULL;

  RETURN NEW;
END;
$$;


--
-- Name: sgp_hr03_vacation_record_audit(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr03_vacation_record_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_action text;
  v_row hr.vacation_record%ROWTYPE;
BEGIN
  v_row := COALESCE(NEW, OLD);
  v_action := CASE TG_OP WHEN 'INSERT' THEN 'CREATE' WHEN 'UPDATE' THEN 'UPDATE' ELSE 'DELETE' END;
  PERFORM public.sgp_append_audit_event(
    v_action,
    'hr.vacation_record'::text,
    v_row.id::text,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'hr.vacation_record'::text,
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object(
      'operation', TG_OP,
      'old', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
      'new', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
    ),
    NULL::text,
    NULL::text,
    NULL::text
  );
  RETURN v_row;
END;
$$;


--
-- Name: sgp_hr04_medical_record_conclude(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr04_medical_record_conclude() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_leave_id uuid;
  v_leave_record_id uuid;
BEGIN
  IF NEW.decision <> 'granted' THEN
    RETURN NEW;
  END IF;

  IF NEW.granted_days IS NULL OR NEW.leave_starts_on IS NULL OR NEW.leave_ends_on IS NULL THEN
    RAISE EXCEPTION 'Granted medical opinion requires granted_days, leave_starts_on, and leave_ends_on'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO hr.medical_leave (
    tenant_id,
    medical_record_id,
    employee_id,
    evaluation_type,
    social_security_benefit,
    absence_reason_id,
    icd_ref,
    cid_code,
    cid_secondary,
    expert_opinion_id,
    granted_days,
    starts_on,
    ends_on,
    status
  )
  VALUES (
    NEW.tenant_id,
    NEW.id,
    NEW.employee_id,
    NEW.evaluation_type,
    NULL,
    NULL,
    NEW.cid_code,
    NEW.cid_code,
    NEW.cid_secondary,
    NEW.id,
    NEW.granted_days,
    NEW.leave_starts_on,
    NEW.leave_ends_on,
    'ACTIVE'::"RecordStatus"
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_leave_id;

  IF v_leave_id IS NULL THEN
    SELECT id INTO v_leave_id
    FROM hr.medical_leave
    WHERE medical_record_id = NEW.id
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  INSERT INTO hr.leave_record (
    tenant_id,
    employee_id,
    absence_reason_id,
    starts_on,
    ends_on,
    days,
    status,
    notes
  )
  SELECT
    NEW.tenant_id,
    NEW.employee_id,
    NULL,
    NEW.leave_starts_on,
    NEW.leave_ends_on,
    NEW.granted_days,
    'ACTIVE'::"RecordStatus",
    'Medical leave generated from official pericia opinion ' || NEW.id::text
  WHERE NOT EXISTS (
    SELECT 1
    FROM hr.leave_record leave_row
    WHERE leave_row.tenant_id = NEW.tenant_id
      AND leave_row.employee_id = NEW.employee_id
      AND leave_row.starts_on = NEW.leave_starts_on
      AND leave_row.ends_on IS NOT DISTINCT FROM NEW.leave_ends_on
      AND leave_row.notes = 'Medical leave generated from official pericia opinion ' || NEW.id::text
  )
  RETURNING id INTO v_leave_record_id;

  UPDATE hr.employee
  SET lifecycle_status = 'ON_LEAVE'::"EmployeeLifecycleStatus",
      updated_at = now()
  WHERE id = NEW.employee_id
    AND tenant_id = NEW.tenant_id;

  PERFORM public.sgp_append_audit_event(
    'CREATE',
    'hr.medical_leave',
    v_leave_id::text,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'hr.medical_leave',
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object(
      'medicalRecordId', NEW.id,
      'leaveRecordId', v_leave_record_id,
      'decision', NEW.decision,
      'grantedDays', NEW.granted_days,
      'cidCode', NEW.cid_code,
      'cidSecondary', NEW.cid_secondary
    ),
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN NEW;
END;
$$;


--
-- Name: sgp_hr04_row_audit(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr04_row_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_action text;
  v_row record;
BEGIN
  v_row := COALESCE(NEW, OLD);
  v_action := CASE TG_OP WHEN 'INSERT' THEN 'CREATE' WHEN 'UPDATE' THEN 'UPDATE' ELSE 'DELETE' END;
  PERFORM public.sgp_append_audit_event(
    v_action,
    TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
    v_row.id::text,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object('operation', TG_OP),
    NULL::text,
    NULL::text,
    NULL::text
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sgp_hr05_leave_record_approval_history(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr05_leave_record_approval_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status_id uuid;
BEGIN
  IF NEW.approved_at IS NULL OR OLD.approved_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_status_id
  FROM hr.functional_status
  WHERE tenant_id = NEW.tenant_id
    AND code IN ('ON_LEAVE', 'AFASTADO', 'LICENCA')
    AND status = 'ACTIVE'::"RecordStatus"
  ORDER BY CASE code WHEN 'ON_LEAVE' THEN 1 WHEN 'AFASTADO' THEN 2 ELSE 3 END
  LIMIT 1;

  IF v_status_id IS NOT NULL THEN
    INSERT INTO hr.employee_status_history (
      tenant_id,
      employee_id,
      functional_status_id,
      starts_on,
      ends_on,
      notes
    )
    VALUES (
      NEW.tenant_id,
      NEW.employee_id,
      v_status_id,
      NEW.starts_on,
      NEW.ends_on,
      'Licenca aprovada: ' || NEW.id::text
    );
  END IF;

  PERFORM public.sgp_append_audit_event(
    'UPDATE',
    'hr.leave_record',
    NEW.id::text,
    NULL::uuid,
    NULLIF(current_setting('app.current_user_sub', true), ''),
    NULLIF(current_setting('app.current_login', true), ''),
    'hr.leave_record',
    NULLIF(current_setting('app.request_id', true), ''),
    jsonb_build_object('approvedAt', NEW.approved_at, 'employeeId', NEW.employee_id),
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN NEW;
END;
$$;


--
-- Name: sgp_hr05_leave_record_validate(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr05_leave_record_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_reason_code text;
BEGIN
  SELECT code INTO v_reason_code
  FROM hr.absence_reason
  WHERE id = NEW.absence_reason_id
    AND tenant_id = NEW.tenant_id;

  IF NEW.absence_reason_id IS NULL
     AND NEW.notes LIKE 'Medical leave generated from official pericia opinion %' THEN
    RETURN NEW;
  END IF;

  IF v_reason_code IS NULL THEN
    RAISE EXCEPTION 'leave_record requires a tenant-scoped absence reason' USING ERRCODE = '23514';
  END IF;

  PERFORM hr.f_validate_leave_eligibility(
    NEW.employee_id,
    v_reason_code,
    NEW.starts_on,
    COALESCE(NEW.days, NEW.ends_on - NEW.starts_on + 1),
    NEW.supporting_document_ref
  );

  IF v_reason_code = 'interesse_particular' THEN
    NEW.paid := false;
  END IF;
  IF NEW.ends_on IS NULL THEN
    NEW.ends_on := NEW.starts_on + (COALESCE(NEW.days, 1) - 1);
  END IF;
  IF NEW.days IS NULL THEN
    NEW.days := NEW.ends_on - NEW.starts_on + 1;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sgp_hr07_cadastral_change_audit(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr07_cadastral_change_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_action text;
  v_id text;
BEGIN
  v_action := TG_OP;
  v_id := COALESCE(NEW.id, OLD.id)::text;
  PERFORM public.sgp_append_audit_event(
    v_action,
    'hr.cadastral_change_request',
    v_id,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sgp_hr08_probation_statutory_only(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr08_probation_statutory_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM hr.employee employee
    LEFT JOIN hr.employment_link link ON link.id = employee.employment_link_id
    WHERE employee.id = NEW.employee_id
      AND employee.tenant_id = NEW.tenant_id
      AND COALESCE(link.contract_type, 'statutory') = 'statutory'
  ) THEN
    RAISE EXCEPTION 'probation_evaluation requires a statutory employee' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sgp_hr08_set_updated_at(); Type: FUNCTION; Schema: hr; Owner: -
--

CREATE FUNCTION hr.sgp_hr08_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


