CREATE FUNCTION payroll_calc.f_fol01_venc_8113c96e(p_employee_id uuid, p_month integer DEFAULT EXTRACT(month FROM CURRENT_DATE), p_year integer DEFAULT EXTRACT(year FROM CURRENT_DATE)) RETURNS numeric
