--
-- Name: career_plan; Type: TABLE; Schema: avaliacao; Owner: -
--

CREATE TABLE avaliacao.career_plan (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    instituting_law text NOT NULL,
    starts_on date NOT NULL,
    ends_on date,
    class_count integer NOT NULL,
    reference_count integer NOT NULL,
    progression_rule text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT career_plan_class_count_positive CHECK ((class_count > 0)),
    CONSTRAINT career_plan_dates_valid CHECK (((ends_on IS NULL) OR (ends_on >= starts_on))),
    CONSTRAINT career_plan_reference_count_positive CHECK ((reference_count > 0))
);

ALTER TABLE ONLY avaliacao.career_plan FORCE ROW LEVEL SECURITY;


--
-- Name: career_plan_job_position; Type: TABLE; Schema: avaliacao; Owner: -
--

CREATE TABLE avaliacao.career_plan_job_position (
    career_plan_id uuid NOT NULL,
    job_position_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY avaliacao.career_plan_job_position FORCE ROW LEVEL SECURITY;


--
-- Name: endpoint_circuit_state; Type: TABLE; Schema: esocial; Owner: -
--

CREATE TABLE esocial.endpoint_circuit_state (
    endpoint_url text NOT NULL,
    opened_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    failure_count integer DEFAULT 0 NOT NULL,
    state esocial.endpoint_circuit_state_status DEFAULT 'CLOSED'::esocial.endpoint_circuit_state_status NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT endpoint_circuit_failure_count_nonnegative_chk CHECK ((failure_count >= 0)),
    CONSTRAINT endpoint_circuit_opened_at_chk CHECK ((((state = 'OPEN'::esocial.endpoint_circuit_state_status) AND (opened_at IS NOT NULL)) OR (state <> 'OPEN'::esocial.endpoint_circuit_state_status)))
);

ALTER TABLE ONLY esocial.endpoint_circuit_state FORCE ROW LEVEL SECURITY;


--
-- Name: esocial_totalizer; Type: TABLE; Schema: esocial; Owner: -
--

CREATE TABLE esocial.esocial_totalizer (
    tenant_id uuid NOT NULL,
    competence date NOT NULL,
    kind esocial.esocial_totalizer_kind NOT NULL,
    source_event_recibo text NOT NULL,
    payload jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
